<?php
global $wp_query;$post_ids = wp_list_pluck($wp_query->posts, "ID");$current_cats = $wp_query->query_vars['cat'];$current_cats = explode(",",$current_cats);$cat_ids = [];foreach ($current_cats as $cat_id) {$cat_ids[] = (int)$cat_id;}$category_data = _opt('pf_frontpage_category_articles_modal',[]);$cat_title = "";foreach ($category_data as $data) {if ($cat_title == "" && $data['cat'] == $cat_ids) {$cat_title = $data['title'];}}if (!$cat_title) {$term = get_term_by('id', $cat_ids[0], 'category');$cat_title = $term ? $term->name : '';}?><div class="clearfix"><?php pf_the_modal_title($cat_title); ?><div class="row post-card-row"><?php do_action('pf_the_taxonomy_articles',$post_ids, $cat_ids); ?></div></div>